mapper.select:
select baseline_id, project_id, frozen_by, frozen_time
from sys_defect_plan_baseline
where project_id = #{projectId}

mapper.update:
update sys_defect_plan_baseline
set frozen_by = #{frozenBy}, frozen_time = #{frozenTime}
where baseline_id = #{baselineId}

mapper.select:
select item_id, baseline_id, defect_id, plan_start_time, plan_end_time from sys_defect_plan_baseline_item where baseline_id = #{baselineId}
and defect_id in #{id}
and 1 = 0
order by defect_id
